Let $E$ be a binary smooth relation on $\mathbb{Q}^k$ that is preserved by $\langle pp_{}\rangle$. If   $E$ contains a min-clean tuple  $\binom{a^1}{b^1}$, then there exist $I\subseteq k$, $m,n\geq1,  q\in \mathbb{Q}$, and $\binom{a^2}{b^2},\ldots,\binom{a^n}{b^n}\in E$ such that for all $a, b \in \mathbb{Q}^k$ the tuple  defined by  
  \begin{equation*}
      \binom{a'}{b'} \mathrel{\mathop:}\mathrel{\mkern-1.2mu}={pp_{q}^{[n+1]}}\left(\binom{a^1}{b^1}, \binom{a^2}{b^2}, \dots, \binom{a^n}{b^n},\binom{a}{b}\right)
  \end{equation*}
  satisfies:
  \begin{itemize}
      \item $I_m(a')=I_m(b')=I$ and $a'\sim_I b'$;
      \item $a'\sim_{[k]\setminus I} a$ and $b'\sim_{[k]\setminus I} b$.
  \end{itemize}

Let $n \geq 2$, and let $R$ be an $n$-ary cyclic relation on $\mathbb{Q}^k$ that is preserved by $\langle pp_{}\rangle$. If $R$ contains a min-clean tuple $t ^1$, then

there exist $I\subseteq [k],  q\in \mathbb{Q}$, and $t^2, \dots, t^n\in R$ such that for all $t \in R$ the tuple $t'$  defined by 
  \begin{equation*}
       t'\mathrel{\mathop:}\mathrel{\mkern-1.2mu}= {pp_q^{[n+1]}} \left(t^1, t^2, \dots, t^n, t\right)
  \end{equation*} 
  satisfies:
  \begin{itemize}
      \item $I_{1}(t'_i)=I$ for all $i \leq n$;
      \item $t'_i\sim_{[k]\setminus I} t_i$ for all $i \leq  n$.
  \end{itemize}

Let $E$ be a binary smooth relation on $\mathbb{Q}^k$ that is preserved by $\langle\ell\ell\rangle$. Let $S \subseteq E$ be smooth such that $S'$ contains a min-clean tuple $\binom{a^1}{b^1}$. Then there exist $I\subseteq k$, $m,n\geq1,  q\in \mathbb{Q}$, and $\binom{a^2}{b^2},\ldots,\binom{a^n}{b^n}\in S'$ such that for all $\binom{a}{b} \in S'$ the tuple  defined by 
  \begin{equation*}
       \binom{a'}{b'}\mathrel{\mathop:}\mathrel{\mkern-1.2mu}= {\ell\ell_q^{[n+1]}} \left(\binom{a^1}{b^1},\binom{a^2}{b^2}, \dots,\binom{a^n}{b^n},\binom{a}{b}\right)
  \end{equation*} 
  satisfies:
  \begin{itemize}
      \item $I_m(a')=I_m(b')=I$ and $a'\sim_I b'$;
      \item $a'\sim_{[k]\setminus I} a$ and $b'\sim_{[k]\setminus I} b$.
  \end{itemize}

Let $n \geq 2$, and let $R$ be an $n$-ary cyclic relation on $\mathbb{Q}^k$ that is preserved by $\langle\ell\ell\rangle$. If $R'$ contains a min-clean tuple $t^1$,

then there exist $I\subseteq [k],  q\in \mathbb{Q}$, and $t^2, \dots, t^n\in R$ such that for all $t \in R'$ the tuple $t'$  defined by 
  \begin{equation*}
       t'\mathrel{\mathop:}\mathrel{\mkern-1.2mu}= {pp_q^{[n+1]}} \left(t^1, t^2, \dots, t^n, t\right)
  \end{equation*} 
  satisfies:
  \begin{itemize}
      \item $I_{1}(t'_i)=I$ for all $i \leq n$;
      \item $t'_i\sim_{[k]\setminus I} t_i$ for all $i \leq  n$.
  \end{itemize}
